Q: How do you set the document title in React? A: <pre><code>import React from 'react';

function useTitle(title: string): void =&gt; {
  React.useEffect(() =&gt; {
    const prevTitle = document.title;
    document.title = title;

    return () =&gt; {
      document.title = prevTitle;
    };
  }, [title]);
}

function MyComponent(): JSX.Element =&gt; {
  useTitle('Title while MyComponent is mounted');

  return &lt;div&gt;My Component&lt;/div&gt;;
}
</code></pre>
<p>This is a pretty straight forward solution, <code>useTitle</code> sets the document title and when the component unmounts it's reset to whatever it was previously.</p>
